package com.example.parcel;

import jakarta.inject.Inject;
import jakarta.validation.Valid;
import jakarta.ws.rs.Consumes;
import jakarta.ws.rs.POST;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.Produces;
import jakarta.ws.rs.core.MediaType;
import jakarta.ws.rs.core.Response;
import java.util.Map;
import org.jboss.resteasy.reactive.server.ServerExceptionMapper;

@Path("/parcels")
@Consumes(MediaType.APPLICATION_JSON)
@Produces(MediaType.APPLICATION_JSON)
public class ParcelResource {
    @Inject
    ParcelService service;

    @POST
    public Response register(@Valid ParcelRequest request) {
        Parcel parcel = service.register(request.parcelId(), request.weightKg());
        return Response.status(Response.Status.CREATED).entity(parcel).build();
    }

    @ServerExceptionMapper
    public Response tooHeavy(ParcelTooHeavyException e) {
        return Response.status(422).entity(Map.of("error", e.getMessage())).build();
    }
}
